where class_code = #{classCode} and is_delete = 0
and class_id != #{excludeClassId}

select count(1) from `ry_rental`.`ry_rental_product_class`
where parent_id = #{parentId} and class_name = #{className} and is_delete = 0
and class_id != #{excludeClassId}

mapper.insert:
insert into `ry_rental`.`ry_rental_product_class`(
    parent_id, ancestors, class_code, class_name, class_level, sort_no, status,
